// A pretend CPU: 16 number boxes (registers), some memory, and a loop.
struct Cpu {
    r: [u32; 16],     // registers r0..r15; r15 = "which instruction next" (PC)
    mem: Vec<u8>,     // memory: just a big array of bytes
}

impl Cpu {
    fn step(&mut self) {
        let pc = self.r[15] as usize;
        let op = self.mem[pc];          // 1. fetch the next instruction
        let a = self.mem[pc + 1] as usize;
        let b = self.mem[pc + 2] as usize;
        self.r[15] += 3;                // move to the following instruction
        match op {                      // 2. decode, 3. execute
            0x01 => self.r[a] = b as u32,                              // LOAD  ra, number
            0x02 => self.r[a] = self.r[a].wrapping_add(self.r[b]),     // ADD   ra, rb
            0x03 => self.r[15] = b as u32,                             // JUMP  to address
            _ => panic!("unknown instruction {op:#x}"),
        }
    }
}

fn main() {
    // Program: r0 = 2; r1 = 3; r0 = r0 + r1
    let program = vec![0x01, 0, 2,  0x01, 1, 3,  0x02, 0, 1];
    let mut cpu = Cpu { r: [0; 16], mem: program };
    for _ in 0..3 { cpu.step(); }
    assert_eq!(cpu.r[0], 5);
    println!("r0 = {}", cpu.r[0]);
}
EOF
rustc -O cpu.rs 2>&1 | tail -3 && ./cpu

