// A pretend CPU: 16 number boxes (registers), some memory, and a loop.

const PROGRAM_COUNTER: usize = 15; // register 15 holds "where is the next instruction"
const INSTRUCTION_SIZE: u32 = 3;   // each instruction is 3 bytes: opcode, first, second

const OPCODE_LOAD_NUMBER: u8 = 0x01; // registers[first] = second
const OPCODE_ADD: u8 = 0x02;         // registers[first] = registers[first] + registers[second]
const OPCODE_JUMP: u8 = 0x03;        // continue running at address `second`

struct Cpu {
    registers: [u32; 16],
    memory: Vec<u8>,
}

impl Cpu {
    fn step(&mut self) {
        // 1. Fetch: read the next instruction from memory.
        let address = self.registers[PROGRAM_COUNTER] as usize;
        let opcode = self.memory[address];
        let first_operand = self.memory[address + 1] as usize;
        let second_operand = self.memory[address + 2] as usize;

        // Point at the following instruction before executing this one.
        self.registers[PROGRAM_COUNTER] += INSTRUCTION_SIZE;

        // 2. Decode and 3. Execute.
        match opcode {
            OPCODE_LOAD_NUMBER => {
                let destination = first_operand;
                let number = second_operand as u32;
                self.registers[destination] = number;
            }
            OPCODE_ADD => {
                let destination = first_operand;
                let source = second_operand;
                self.registers[destination] =
                    self.registers[destination].wrapping_add(self.registers[source]);
            }
            OPCODE_JUMP => {
                let target_address = second_operand as u32;
                self.registers[PROGRAM_COUNTER] = target_address;
            }
            unknown => panic!("unknown instruction {unknown:#x} at address {address}"),
        }
    }
}

fn main() {
    // Program: r0 = 2; r1 = 3; r0 = r0 + r1
    let program = vec![
        OPCODE_LOAD_NUMBER, 0, 2,
        OPCODE_LOAD_NUMBER, 1, 3,
        OPCODE_ADD,         0, 1,
    ];
    let mut cpu = Cpu { registers: [0; 16], memory: program };

    for _ in 0..3 {
        cpu.step();
    }

    assert_eq!(cpu.registers[0], 5);
    println!("register 0 = {}", cpu.registers[0]);
}

